-- metric_id: bku.business_enumerated_count
-- bindings: []
SELECT COUNT(*) AS eligible_rows,COALESCE(SUM(CASE WHEN 1=1 AND 1=1 THEN 1 ELSE 0 END),0) AS numerator,COALESCE(SUM(CASE WHEN 1=1 THEN 1 ELSE 0 END),0) AS denominator FROM (SELECT * FROM (SELECT b."__row_id",b."__import_id",b."__clean_hash",b."__key",b."__version_normalized",b."__key_valid",b."__conflict",b."assignment_id",b."assignment_date_modified",b."code_identity",b."listing_assignment",b."kode_kecamatan",b."kecamatan",b."kode_desa",b."desa_kelurahan",b."kode_sls_subsls",b."sls_subsls",b."nomor_bangunan",b."nama_bangunan_usaha",b."nama_lookup_prelist",b."alamat_prelist",b."jalan_domisili",b."kode_penggunaan_bangunan",b."penggunaan_bangunan",b."kode_keberadaan_bku",b."keberadaan_bku",b."kode_keberadaan_keluarga",b."keberadaan_keluarga",b."geotag_accuracy",b."geotag_latitude",b."geotag_longitude",b."status_assignment",b."__batch_id",b."__source_sha256" FROM mart_bku b WHERE b.kode_penggunaan_bangunan='1' AND b.kode_keberadaan_bku IN ('1','2') AND EXISTS (SELECT 1 FROM mart_assignment_tgr a WHERE a.assignment_id=b.assignment_id AND a.status_assignment IN ('APPROVED BY Pengawas','COMPLETED BY Admin Kabupaten'))) LIMIT -1 OFFSET 0) e WHERE 1=1;

-- metric_id: bku.count
-- bindings: []
SELECT COUNT(*) AS eligible_rows,COALESCE(SUM(CASE WHEN 1=1 AND 1=1 THEN 1 ELSE 0 END),0) AS numerator,COALESCE(SUM(CASE WHEN 1=1 THEN 1 ELSE 0 END),0) AS denominator FROM (SELECT "__version_normalized","assignment_id","kode_keberadaan_bku" FROM "mart_bku" LIMIT -1 OFFSET 0) e WHERE 1=1;

-- metric_id: bku.existence_distribution
-- bindings: []
SELECT e."kode_keberadaan_bku",COUNT(*) AS eligible_rows,COALESCE(SUM(CASE WHEN 1=1 AND 1=1 THEN 1 ELSE 0 END),0) AS numerator,COALESCE(SUM(CASE WHEN 1=1 THEN 1 ELSE 0 END),0) AS denominator FROM (SELECT "__version_normalized","assignment_id","kode_keberadaan_bku" FROM "mart_bku" LIMIT -1 OFFSET 0) e WHERE 1=1 GROUP BY e."kode_keberadaan_bku";
